package vendor

import spinal.core._

/** GTS Direct PHY variant from agilex5/gts/gen_ip.sh (`variant`: olt, onu, eth): duplex, single width, parallel data
  * first bit in bit 0. */
case class GtsDuplex(variant: String, lockToRef: Boolean = false) extends BlackBox {
  setDefinitionName(variant)
  val i_rx_cdr_refclk_p, i_tx_pll_refclk_p, i_pma_cu_clk = in Bool ()
  val i_tx_reset, i_rx_reset = in Bool ()
  val o_tx_reset_ack, o_rx_reset_ack, o_tx_ready, o_rx_ready = out Bool ()
  val i_tx_coreclkin, i_rx_coreclkin = in Bool ()
  val o_tx_clkout, o_rx_clkout = out Bool ()
  val i_src_rs_grant = in Bool ()
  val o_src_rs_req = out Bool ()
  val o_tx_serial_data, o_tx_serial_data_n = out Bool ()
  val i_rx_serial_data, i_rx_serial_data_n = in Bool ()
  val o_tx_pll_locked, o_rx_is_lockedtodata, o_rx_is_lockedtoref = out Bool ()
  val i_rx_set_locktoref = lockToRef generate in(Bool())
  val i_tx_parallel_data = in Bits (80 bits)
  val o_rx_parallel_data = out Bits (80 bits)
  noIoPrefix()
}

/** TX-only GTS variant from agilex5/gts/gen_ip.sh (ben_tx). */
case class GtsTx(variant: String) extends BlackBox {
  setDefinitionName(variant)
  val i_tx_pll_refclk_p, i_pma_cu_clk, i_tx_reset, i_tx_coreclkin, i_src_rs_grant = in Bool ()
  val o_tx_reset_ack, o_tx_ready, o_tx_clkout, o_src_rs_req, o_tx_serial_data, o_tx_serial_data_n, o_tx_pll_locked = out Bool ()
  val i_tx_parallel_data = in Bits (80 bits)
  noIoPrefix()
}

/** Shared reference clock and reset sequencer of the GTS lanes (one req/grant pair per lane). */
case class GtsSrcss(lanes: Int) extends BlackBox {
  setDefinitionName("srcss")
  val o_src_rs_grant = out Bits (lanes bits)
  val i_src_rs_priority, i_src_rs_req = in Bits (lanes bits)
  val o_pma_cu_clk = out Bool ()
  val i_src_rs_refclk_status_bus = in Bits (10 bits)
  val o_refclk_fail_status = out Bits (8 bits)
  val o_refclk_on_ack = out Bool ()
  val i_refclk_on = in Bits (10 bits)
  val o_src_rs_refclk_cmd_bus = out Bits (10 bits)
  noIoPrefix()
}

/** Clock network divider from gen_ip.sh (pon_clocks): inclk and inclk / 2, aligned and timed as related clocks. */
case class PonClocks() extends BlackBox {
  setDefinitionName("pon_clocks")
  val inclk = in Bool ()
  val clock_div1x, clock_div2x = out Bool ()
  noIoPrefix()
}

/** I/O PLL from gen_ip.sh (helper_pll): 155.357 MHz from a 50 MHz board oscillator, the VCXO loop's helper clock. */
case class HelperPll() extends BlackBox {
  setDefinitionName("helper_pll")
  val refclk, rst = in Bool ()
  val outclk_0, locked = out Bool ()
  noIoPrefix()
}

/** The OLT cage lane with its two DR profiles (dr_top, generated by quartus_tlg from the gen_ip.sh olt and olt_1g25
  * variants, see fit.sh): the shared channel ports, then each profile's ports as a GtsDuplex. */
case class GtsDrLane() extends BlackBox {
  setDefinitionName("dr_top")
  val i_dr_lavmm_addr_ch0 = in Bits (21 bits)
  val i_dr_lavmm_be_ch0 = in Bits (4 bits)
  val i_dr_lavmm_clk_ch0, i_dr_lavmm_read_ch0, i_dr_lavmm_rstn_ch0, i_dr_lavmm_write_ch0 = in Bool ()
  val i_dr_lavmm_wdata_ch0 = in Bits (32 bits)
  val o_dr_lavmm_rdata_ch0 = out Bits (32 bits)
  val o_dr_lavmm_rdata_valid_ch0, o_dr_lavmm_waitreq_ch0 = out Bool ()
  val i_pma_cu_clk_bank0, i_rs_grant_ch0, i_src_pause_request_ch0 = in Bool ()
  val o_rs_request_ch0, o_src_pause_grant_ch0 = out Bool ()
  val one_hot_sel = in Bits (2 bits)
  val i_rx_serial_data_p_ch0, i_rx_serial_data_n_ch0 = in Bool ()
  val o_tx_serial_data_p_ch0, o_tx_serial_data_n_ch0 = out Bool ()
  case class Profile(suffix: String) {
    def port[T <: Data](name: String, data: T): T = data.setName(s"${name}_$suffix")
    val i_tx_pll_refclk_p = port("i_tx_pll_refclk_p", in Bool ())
    val i_rx_cdr_refclk_p = port("i_rx_cdr_refclk_p", in Bool ())
    val i_tx_coreclkin = port("i_tx_coreclkin", in Bool ())
    val i_rx_coreclkin = port("i_rx_coreclkin", in Bool ())
    val o_tx_clkout = port("o_tx_clkout", out Bool ())
    val o_rx_clkout = port("o_rx_clkout", out Bool ())
    val i_tx_reset = port("i_tx_reset", in Bool ())
    val i_rx_reset = port("i_rx_reset", in Bool ())
    val i_rx_set_locktoref = port("i_rx_set_locktoref", in Bool ())
    val o_tx_reset_ack = port("o_tx_reset_ack", out Bool ())
    val o_rx_reset_ack = port("o_rx_reset_ack", out Bool ())
    val o_tx_ready = port("o_tx_ready", out Bool ())
    val o_rx_ready = port("o_rx_ready", out Bool ())
    val o_tx_pll_locked = port("o_tx_pll_locked", out Bool ())
    val o_rx_is_lockedtodata = port("o_rx_is_lockedtodata", out Bool ())
    val o_rx_is_lockedtoref = port("o_rx_is_lockedtoref", out Bool ())
    val i_tx_parallel_data = port("i_tx_parallel_data", in Bits (80 bits))
    val o_rx_parallel_data = port("o_rx_parallel_data", out Bits (80 bits))
  }
  val gpon = Profile("olt_inst")
  val oneG25 = Profile("olt_1g25_inst") // dr_top's one_hot_sel bit 0 (its mux port order: olt, olt_1g25)
  noIoPrefix()
}

/** GTS dynamic reconfiguration controller from gen_ip.sh (dr_ctrl): host CSRs (byte addresses 0-0x7C) on the
  * management clock, the channel's local AVMM and the profile select towards dr_top. */
case class GtsDrCtrl() extends BlackBox {
  setDefinitionName("dr_ctrl")
  val i_rst_n, i_csr_clk, i_cpu_clk = in Bool ()
  val o_profile_id = out Bits (15 bits)
  val o_in_progress, o_err_status, o_fast_sim_clk_sel = out Bool ()
  val i_host_avmm_address = in UInt (7 bits)
  val i_host_avmm_read, i_host_avmm_write = in Bool ()
  val i_host_avmm_writedata = in Bits (32 bits)
  val o_host_avmm_readdata = out Bits (32 bits)
  val o_host_avmm_readdatavalid, o_host_avmm_waitrequest = out Bool ()
  val o_one_hot_sel = out Bits (2 bits)
  val o_src_pause_request = out Bool ()
  val i_src_pause_grant = in Bool ()
  val o_ch0_lavmm_addr = out Bits (21 bits)
  val o_ch0_lavmm_be = out Bits (4 bits)
  val o_ch0_lavmm_write, o_ch0_lavmm_read, o_ch0_lavmm_rstn = out Bool ()
  val o_ch0_lavmm_wdata = out Bits (32 bits)
  val i_ch0_lavmm_rdata = in Bits (32 bits)
  val i_ch0_lavmm_rdata_valid, i_ch0_lavmm_waitreq = in Bool ()
  noIoPrefix()
}

/** Clock network mux from gen_ip.sh (olt_clock_mux): inclk0x or inclk1x, switched only while their logic is in reset. */
case class ClockMux() extends BlackBox {
  setDefinitionName("olt_clock_mux")
  val inclk0x, inclk1x = in Bool ()
  val clkselect = in Bool ()
  val outclk = out Bool ()
  noIoPrefix()
}
